import{et as e,mt as t,s as n,tt as r}from"./chunks/framework.CHi0mXvr.js";var i=JSON.parse(`{"title":"Daily Scrum","description":"A step-by-step guide to conducting an effective Daily Scrum. Check out the core principles and practical tips of this 15-minute meeting for strengthening agile team collaboration, checking progress, and removing obstacles.","frontmatter":{"title":"Daily Scrum","description":"A step-by-step guide to conducting an effective Daily Scrum. Check out the core principles and practical tips of this 15-minute meeting for strengthening agile team collaboration, checking progress, and removing obstacles.","head":[["meta",{"name":"keywords","content":"Daily Scrum, Scrum Meeting, Agile, Agile Methodology, Scrum Master, Team Collaboration, Daily Meeting, How to conduct Scrum, Agile Coaching, Team Obstacle Resolution"}],["meta",{"property":"og:title","content":"Scrumban"}],["meta",{"property":"og:description","content":"A step-by-step guide to conducting an effective Daily Scrum. Check out the core principles and practical tips of this 15-minute meeting for strengthening agile team collaboration, checking progress, and removing obstacles."}],["meta",{"property":"og:image","content":"https://empasy.io/docs/images/favicon.png"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/agile/activity.html"}],["link",{"rel":"canonical","href":"https://empasy.io/docs/en/agile/dailyScrum.html"}]],"sort":3000},"headers":[],"relativePath":"en/agile/dailyScrum.md","filePath":"en/agile/dailyScrum.md","lastUpdated":1786257982000}`),a={name:`en/agile/dailyScrum.md`};function o(n,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[r(`<h1 id="✅-how-to-conduct-a-daily-scrum" tabindex="-1">✅ How to Conduct a Daily Scrum <a class="header-anchor" href="#✅-how-to-conduct-a-daily-scrum" aria-label="Permalink to “✅ How to Conduct a Daily Scrum”">​</a></h1><ol><li><strong>Fixed Time &amp; Location</strong></li></ol><ul><li>Same time every day (e.g., 9:00 AM)</li><li>Same location (meeting room or online video conference)</li></ul><ol start="2"><li><strong>Participants</strong></li></ol><ul><li>All development team members (Developers, QA, etc.)</li><li>Scrum Master (facilitator), PO can be an observer</li></ul><ol start="3"><li><strong>How to Proceed</strong></li></ol><ul><li><p>Duration is <strong>within 15 minutes</strong></p></li><li><p>Team members <strong>take turns sharing</strong></p></li><li><p>Briefly answer based on <strong>3 questions</strong></p><ol><li>What did you do yesterday?</li><li>What will you do today?</li><li>Are there any obstacles preventing progress?</li></ol></li></ul><ol start="4"><li><strong>Important Principles</strong></li></ol><ul><li>Detailed technical explanation ❌ → Focus on &quot;Sharing&quot;</li><li>Obstacles are discussed separately after the Scrum</li><li>The purpose is not reporting, but <strong>team synchronization</strong></li></ul><hr><h1 id="🎤-daily-scrum-practical-example-script" tabindex="-1">🎤 Daily Scrum Practical Example Script <a class="header-anchor" href="#🎤-daily-scrum-practical-example-script" aria-label="Permalink to “🎤 Daily Scrum Practical Example Script”">​</a></h1><h2 id="basic-information" tabindex="-1">Basic Information <a class="header-anchor" href="#basic-information" aria-label="Permalink to “Basic Information”">​</a></h2><ul><li><strong>Time</strong>: Every morning at 10:00 (within 15 minutes)</li><li><strong>Attendees</strong>: Entire development team, Scrum Master, Product Owner (PO) if necessary</li><li><strong>Format</strong>: Stand-up (video conference for remote)</li></ul><hr><h2 id="_1-opening-remarks-and-confirming-the-purpose-of-the-meeting-2-minutes" tabindex="-1">1. Opening Remarks and Confirming the Purpose of the Meeting (2 minutes) <a class="header-anchor" href="#_1-opening-remarks-and-confirming-the-purpose-of-the-meeting-2-minutes" aria-label="Permalink to “1. Opening Remarks and Confirming the Purpose of the Meeting (2 minutes)”">​</a></h2><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Good morning. We will begin the Daily Scrum. Today again, please share what you did yesterday, what you will do today, and any obstacles you have.&quot;</p></blockquote><hr><h2 id="_2-sharing-progress-by-team-member-10-minutes" tabindex="-1">2. Sharing Progress by Team Member (10 minutes) <a class="header-anchor" href="#_2-sharing-progress-by-team-member-10-minutes" aria-label="Permalink to “2. Sharing Progress by Team Member (10 minutes)”">​</a></h2><h3 id="developer-kim" tabindex="-1">Developer Kim <a class="header-anchor" href="#developer-kim" aria-label="Permalink to “Developer Kim”">​</a></h3><blockquote><p>&quot;Yesterday, I completed the user login API development. Today, I plan to implement the user profile inquiry feature. There are no particular obstacles at the moment.&quot;</p></blockquote><h3 id="designer-lee" tabindex="-1">Designer Lee <a class="header-anchor" href="#designer-lee" aria-label="Permalink to “Designer Lee”">​</a></h3><blockquote><p>&quot;Yesterday, I finished the UI design for the payment page and delivered it to the dev team. Today, I plan to start designing the admin page. However, there is a part that requires consultation with the dev part, so can we have a short meeting in the afternoon?&quot;</p></blockquote><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Yes, I will coordinate the schedule with the related team members after the meeting.&quot;</p></blockquote><h3 id="backend-park" tabindex="-1">Backend Park <a class="header-anchor" href="#backend-park" aria-label="Permalink to “Backend Park”">​</a></h3><blockquote><p>&quot;I worked on DB optimization yesterday, and I plan to conduct performance testing today. However, the CPU usage of the test server is high, so I think monitoring is needed.&quot;</p></blockquote><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;I will record it as an obstacle and discuss it with the infrastructure team after the meeting.&quot;</p></blockquote><h3 id="qa-jung" tabindex="-1">QA Jung <a class="header-anchor" href="#qa-jung" aria-label="Permalink to “QA Jung”">​</a></h3><blockquote><p>&quot;Yesterday, I completed testing the login feature, and today I plan to start testing the newly added payment feature. There are a few places in the test scenario that need confirmation from the dev team.&quot;</p></blockquote><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;I will connect you directly with the relevant developer after the meeting.&quot;</p></blockquote><hr><h2 id="_3-summarizing-obstacles-and-establishing-an-action-plan-2-minutes" tabindex="-1">3. Summarizing Obstacles and Establishing an Action Plan (2 minutes) <a class="header-anchor" href="#_3-summarizing-obstacles-and-establishing-an-action-plan-2-minutes" aria-label="Permalink to “3. Summarizing Obstacles and Establishing an Action Plan (2 minutes)”">​</a></h2><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Summarizing the obstacles shared so far:</p><ol><li>Need a design-dev consultation meeting</li><li>Test server CPU usage issue</li><li>Need to confirm QA test scenarios</li></ol><p>I will coordinate with each person in charge regarding these three items.&quot;</p></blockquote><hr><h2 id="_4-closing-the-meeting-1-minute" tabindex="-1">4. Closing the Meeting (1 minute) <a class="header-anchor" href="#_4-closing-the-meeting-1-minute" aria-label="Permalink to “4. Closing the Meeting (1 minute)”">​</a></h2><p><strong>Scrum Master</strong>:</p><blockquote><p>&quot;Everyone clearly confirmed what to do today, and obstacles have been identified. Let&#39;s wrap up the meeting here, and those who need to, please continue the discussion separately. Have a great day everyone!&quot;</p></blockquote><hr><h2 id="💡-tips-for-operating-an-effective-daily-scrum" tabindex="-1">💡 Tips for Operating an Effective Daily Scrum <a class="header-anchor" href="#💡-tips-for-operating-an-effective-daily-scrum" aria-label="Permalink to “💡 Tips for Operating an Effective Daily Scrum”">​</a></h2><ul><li><strong>Punctuality</strong>: Recommend standing up to keep the 15-minute rule</li><li><strong>No Problem-Solving Meetings</strong>: Secure a separate time for deep discussions</li><li><strong>Participation of All Team Members</strong>: Create an atmosphere where everyone can speak evenly</li><li><strong>Utilize Visual Aids</strong>: Use Kanban boards, task management tools, etc. together</li><li><strong>Focus on Obstacles</strong>: Must establish an action plan for problem-solving</li></ul><hr><h2 id="📝-example-record" tabindex="-1">📝 Example Record <a class="header-anchor" href="#📝-example-record" aria-label="Permalink to “📝 Example Record”">​</a></h2><table tabindex="0"><thead><tr><th>Person in Charge</th><th>What was done yesterday</th><th>What to do today</th><th>Obstacles</th></tr></thead><tbody><tr><td>Developer Kim</td><td>Completed login API dev</td><td>Implement profile inquiry</td><td>None</td></tr><tr><td>Designer Lee</td><td>Completed payment page UI</td><td>Start admin page design</td><td>Need to consult with dev team</td></tr><tr><td>Backend Park</td><td>DB optimization work</td><td>Conduct performance test</td><td>Test server CPU usage issue</td></tr><tr><td>QA Jung</td><td>Completed login test</td><td>Start payment feature test</td><td>Need to confirm test scenario</td></tr></tbody></table><hr><h1 id="✅-daily-scrum-checklist-for-facilitator" tabindex="-1">✅ Daily Scrum Checklist for Facilitator <a class="header-anchor" href="#✅-daily-scrum-checklist-for-facilitator" aria-label="Permalink to “✅ Daily Scrum Checklist for Facilitator”">​</a></h1><h2 id="📌-facilitator-scrum-master-checklist" tabindex="-1">📌 Facilitator (Scrum Master) Checklist <a class="header-anchor" href="#📌-facilitator-scrum-master-checklist" aria-label="Permalink to “📌 Facilitator (Scrum Master) Checklist”">​</a></h2><ul><li>[ ] Started at the same time/location (or online) every day?</li><li>[ ] Ready to finish within 15 minutes?</li><li>[ ] Guided each team member to share only the 3 items: <strong>Yesterday/Today/Obstacles</strong>?</li><li>[ ] Recorded shared <strong>Obstacles (Blocking Issues)</strong> for separate Follow-up?</li><li>[ ] Called only those who need an additional meeting to resolve issues after the Scrum?</li></ul><hr><h2 id="📌-individual-team-member-sharing-checklist" tabindex="-1">📌 Individual Team Member Sharing Checklist <a class="header-anchor" href="#📌-individual-team-member-sharing-checklist" aria-label="Permalink to “📌 Individual Team Member Sharing Checklist”">​</a></h2><ul><li>[ ] What did I complete yesterday?</li><li>[ ] What will I do today?</li><li>[ ] Are there any obstacles preventing progress?</li></ul><p>👉 Keep sharing <strong>short and clear (1~2 sentences)</strong> 👉 No problem-solving discussion ❌ (separately after Scrum)</p><hr><h2 id="📝-team-member-sharing-example-template" tabindex="-1">📝 Team Member Sharing Example Template <a class="header-anchor" href="#📝-team-member-sharing-example-template" aria-label="Permalink to “📝 Team Member Sharing Example Template”">​</a></h2><div class="language-"><button title="Copy code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Name]</span></span>
<span class="line"><span>- Yesterday:</span></span>
<span class="line"><span>- Today:</span></span>
<span class="line"><span>- Obstacle:</span></span></code></pre></div><hr><h2 id="📊-team-entire-scrum-board-example-whiteboard-online-collaboration-tool" tabindex="-1">📊 Team Entire Scrum Board Example (Whiteboard / Online Collaboration Tool) <a class="header-anchor" href="#📊-team-entire-scrum-board-example-whiteboard-online-collaboration-tool" aria-label="Permalink to “📊 Team Entire Scrum Board Example (Whiteboard / Online Collaboration Tool)”">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>What was done yesterday</th><th>What to do today</th><th>Obstacles (Blocking Issue)</th></tr></thead><tbody><tr><td>Chulsoo</td><td>Completed login API refactoring</td><td>Start Google social login integration</td><td>Cannot access Google OAuth docs</td></tr><tr><td>Younghee</td><td>Write sign-up test cases and execute some</td><td>Complete sign-up feature test and bug report</td><td>Test server disconnects frequently</td></tr><tr><td>Minsoo</td><td>Dashboard UI work</td><td>Apply chart library and API integration</td><td>Latest API spec doc not shared</td></tr></tbody></table><hr><p>👉 By doing this, team members just have to <strong>speak based on the checklist</strong> every day, and the Scrum Master just has to <strong>update the table</strong>, solving recording and sharing simultaneously.</p><hr>`,64)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};